document.addEventListener('DOMContentLoaded', () => {
    const todoList = document.getElementById('s9-todo-list');
    const doingList = document.getElementById('s9-doing-list');
    const doneList = document.getElementById('s9-done-list');

    todoList.addEventListener('click', handleButtonClick);
    doingList.addEventListener('click', handleButtonClick);
    doneList.addEventListener('click', handleButtonClick);

    function handleButtonClick(event) {
        if (event.target.classList.contains('s9-right')) {
            moveCardRight(event.target.parentElement);
        } else if (event.target.classList.contains('s9-left')) {
            moveCardLeft(event.target.parentElement);
        }
    }

    function moveCardRight(card) {
        const currentList = card.parentElement;
        const nextList = getNextList(currentList);

        if (nextList) {
            nextList.appendChild(card);
        }
    }

    function moveCardLeft(card) {
        const currentList = card.parentElement;
        const previousList = getPreviousList(currentList);

        if (previousList) {
            previousList.appendChild(card);
        }
    }

    function getNextList(currentList) {
        if (currentList.id === 's9-todo-list') {
            return doingList;
        } else if (currentList.id === 's9-doing-list') {
            return doneList;
        }
        return null;
    }

    function getPreviousList(currentList) {
        if (currentList.id === 's9-doing-list') {
            return todoList;
        } else if (currentList.id === 's9-done-list') {
            return doingList;
        }
        return null;
    }
});

